'use strict';
// Keep old evidence and scores intact when the roadmap changes.
if(!S.transformationVersion){S.legacyDays=JSON.parse(JSON.stringify(S.days));S.days={};S.transformationVersion=1;S.certifications={};S.phaseProgress={};save();}
S.certifications ||= {}; S.phaseProgress ||= {}; S.solutionStatus ||= {};
const phaseTicks=id=>S.phaseProgress[S.person]?.[id]||[];
function transformationRoadmap(){return `<section class="panel section-space" id="transformation"><p class="eyebrow">LEADERSHIP ROADMAP · DECEMBER 2026 → 31 MARCH 2027 → 30 JUNE 2027</p><h2>One transformation. Three evidence gates.</h2><div class="actions">${T.phases.map((p,i)=>`<button data-phase="${p.id}" aria-pressed="${i===0}">${esc(p.name)}</button>`).join('')}</div><div id="phaseDetail" class="section-space"></div><p class="hint">Targets: 8 industry reference solutions · 10 squads · 10 mentors · 2–3 role-relevant certifications per engineer where feasible · 2–3 pilots subject to access · 100% offered formal assessment. Participant count to confirm.</p><p class="hint">Internal academy recognition is independent of any official Microsoft Frontier Transformation Engineer program. Learning-design inspiration does not imply affiliation, endorsement or eligibility.</p></section>`;}
function bindPhases(){function show(id){const p=T.phases.find(p=>p.id===id),ticks=phaseTicks(id);all('[data-phase]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.phase===id));$('#phaseDetail').innerHTML=`<div class="grid-two"><div><p class="eyebrow">${p.date}</p><h3>${p.name}</h3><p>${p.outcome}</p>${tag('Assessment: '+p.gate,'pink')}<p class="hint">Personal evidence milestones · ${ticks.length}/${p.milestones.length} self-reported. These checks do not award a recognition gate.</p>${progress(Math.round(ticks.length/p.milestones.length*100))}</div><div>${p.milestones.map((m,i)=>`<label class="check"><input type="checkbox" data-milestone="${i}" ${ticks.includes(i)?'checked':''}><span>${esc(m)}</span></label>`).join('')}<a class="button" href="reviews.html">Record evidence review</a></div></div>`;all('[data-milestone]').forEach(b=>b.onchange=()=>{S.phaseProgress[S.person]||={};const a=phaseTicks(id),n=Number(b.dataset.milestone);S.phaseProgress[S.person][id]=b.checked?[...a,n]:a.filter(x=>x!==n);save();show(id);});}all('[data-phase]').forEach(b=>b.onclick=()=>show(b.dataset.phase));show('dec');}
function domains(){ $('#main').innerHTML=head('DOMAIN SOLUTIONS','Eight industries. Measurable customer value.','Eight domain squads plus two specialist squads: platform engineering and agentic AI accelerators. All solutions below are proposed briefs, not deployed customer systems.')+`<section class="panel"><h2>Shared delivery standard</h2><p>Every solution needs a problem statement, approved or synthetic data, ingestion and transformation, quality checks, a governed analytical model, an agentic workflow, a Power BI dashboard, CI/CD and monitoring outline, KPI baseline and a 5–10-minute business demo.</p><p class="hint">Agents explain and recommend by default. Data changes, pipeline retries and business actions require scoped permissions, human approval where needed, trace logs and rollback/failure handling. No agent or cloud workload runs from this demo.</p></section><div class="grid-two section-space">${T.domains.map((d,i)=>`<article class="panel"><p class="eyebrow">DOMAIN SQUAD ${i+1}</p><h2>${esc(d.name)}</h2><h3>${esc(d.problem)}</h3><p>${esc(d.agent)}</p>${tag(d.kpi,'blue')}<details class="section-space"><summary>Solution blueprint and deliverables</summary><dl><dt>Data</dt><dd>${esc(d.data)}; use synthetic data until access is approved.</dd><dt>Architecture & pipeline</dt><dd>Source ingestion → Fabric or Databricks medallion layers → governed serving model → scoped agent tools and Power BI.</dd><dt>Quality</dt><dd>Schema, null, duplicate and business-rule checks; quarantine exceptions and record lineage.</dd><dt>Agent</dt><dd>${esc(d.agent)}. Recommendations require an accountable human decision owner.</dd><dt>Analytics & KPI</dt><dd>${esc(d.kpi)}: establish baseline, measurement window and owner before claiming improvement.</dd><dt>Delivery</dt><dd>December MVP; Q1 hardened solution and stakeholder walkthrough; Q2 pilot, measured results, reusable assets and architecture defense.</dd></dl><a href="catalog.html">Explore supporting modules</a></details><label class="field section-space">Squad delivery status · local demo<select data-solution="${i}">${['Proposed','Discovery','MVP prototype','Hardened','Pilot'].map(s=>`<option ${s===(S.solutionStatus[i]||'Proposed')?'selected':''}>${s}</option>`).join('')}</select></label></article>`).join('')}</div>`;all('[data-solution]').forEach(e=>e.onchange=()=>{S.solutionStatus[e.dataset.solution]=e.value;save();toast('Demo squad status updated.');});}
function certifications(){ $('#main').innerHTML=head('CERTIFICATION PATHWAYS','Choose credentials that serve the role.','Aim for one relevant core certification in Q1 and 2–3 by June where feasible. Credentials supplement delivery evidence; they do not confer senior FDE readiness.')+`<section class="panel"><p><b>Official sources checked 24 November 2026.</b> Titles and codes below link to their providers. Recheck exam availability and requirements before booking. Learning material may be free; professional exams and practical cloud services generally cost money.</p><p class="hint">Essential means one relevant primary-platform option, not every credential. All windows and classifications are academy recommendations. Status controls are self-reported demo data, not provider verification.</p></section><div class="toolbar section-space">${[['certProvider','Provider', [...new Set(T.certs.map(c=>c.provider))]],['certRole','Role',[...new Set(T.certs.map(c=>c.role))]],['certLevel','Pathway level',[...new Set(T.certs.map(c=>c.level))]]].map(([id,label,values])=>`<label>${label}<select id="${id}"><option value="">All</option>${values.map(v=>`<option>${v}</option>`).join('')}</select></label>`).join('')}</div><p id="certCount" role="status"></p><div class="grid-three" id="certGrid"></div>`;function render(){const cs=T.certs.filter(c=>(!$('#certProvider').value||c.provider===$('#certProvider').value)&&(!$('#certRole').value||c.role===$('#certRole').value)&&(!$('#certLevel').value||c.level===$('#certLevel').value));$('#certCount').textContent=cs.length+' pathways';$('#certGrid').innerHTML=cs.map(c=>`<article class="course-card">${tag(c.level,'blue')}<p class="eyebrow section-space">${c.provider} · ${c.code}</p><h3>${c.title}</h3><p>${c.role} · ${c.type}</p><p><b>Recommended:</b> ${c.window}</p><p>${c.note}</p><p class="hint">${c.status}</p><a href="${c.url}" target="_blank" rel="noopener noreferrer">Official provider details</a><label class="field section-space">Your status · local demo<select data-cert="${c.code}">${['Not planned','Planned','Studying','Attained (self-reported)'].map(s=>`<option ${s===(S.certifications[S.person]?.[c.code]||'Not planned')?'selected':''}>${s}</option>`).join('')}</select></label></article>`).join('')||'<p class="empty">No pathways match these filters.</p>';all('[data-cert]').forEach(e=>e.onchange=()=>{S.certifications[S.person]||={};S.certifications[S.person][e.dataset.cert]=e.value;save();toast('Self-reported credential status saved locally.');});}['certProvider','certRole','certLevel'].forEach(id=>$('#'+id).onchange=render);render();}
function leadershipExtension(){const certStates=Object.values(S.certifications).flatMap(x=>Object.entries(x)).filter(([code])=>code!=='ACADEMY'),attained=certStates.filter(([,s])=>s.startsWith('Attained')).length,planned=certStates.filter(([,s])=>s!=='Not planned').length;$('#main').insertAdjacentHTML('beforeend',`<section class="panel section-space"><p class="eyebrow">TRANSFORMATION DELIVERY · LOCAL DEMO</p><h2>Squads, credentials and interventions</h2>${metrics([['Certification plans',planned,'Across sample profiles · excludes learning badges'],['Self-reported attained',attained,'Not provider-verified'],['MVP prototypes',Object.values(S.solutionStatus).filter(s=>['MVP prototype','Hardened','Pilot'].includes(s)).length,'Demo status · target 8'],['Pilots',Object.values(S.solutionStatus).filter(s=>s==='Pilot').length,'Demo status · target 2–3']])}<div class="table-wrap"><table><thead><tr><th>Squad</th><th>Delivery status</th><th>KPI</th><th>Risk / next intervention</th></tr></thead><tbody>${T.domains.map((d,i)=>`<tr><td>${d.name}</td><td>${esc(S.solutionStatus[i]||'Proposed')}</td><td>${d.kpi}</td><td>Confirm data access, KPI baseline and mentor evidence review.</td></tr>`).join('')}<tr><td>Platform engineering</td><td>Proposed</td><td>Deployment reliability</td><td>Provide CI/CD, security and monitoring templates.</td></tr><tr><td>Agentic AI accelerators</td><td>Proposed</td><td>Evaluation quality</td><td>Provide scoped tools, evaluation harness and approval patterns.</td></tr></tbody></table></div><p class="hint">No live squad telemetry is connected. Change domain statuses in Domain Solutions. Learning completion and mentor scores above calculate from local records.</p><h3>Recognition gates by sample participant</h3><div class="table-wrap"><table><thead><tr><th>Participant</th><th>Foundation</th><th>Practitioner</th><th>Senior readiness</th></tr></thead><tbody>${D.people.map(p=>`<tr><td>${esc(p.name)}</td>${['Foundation','Practitioner','Senior'].map(g=>{const r=S.reviews.filter(r=>r.person===p.id&&r.assessmentGate?.includes(g)).at(-1);return `<td>${r?esc(r.decision):'Not assessed'}</td>`}).join('')}</tr>`).join('')}</tbody></table></div></section>`);}
({index:overview,catalog,course,resources,worklog,reviews,insights,domains,certifications}[page]||overview)();
if(page==='index'){
 $('.hero').insertAdjacentHTML('afterend',transformationRoadmap());bindPhases();
 $('#transformation').insertAdjacentHTML('afterend',`<div class="grid-two section-space"><section class="panel"><h2>Technology learning effort</h2>${T.effort.map(([n,v])=>`<div class="bar-row"><span>${n}</span>${progress(v)}<b>${v}%</b></div>`).join('')}<p class="hint">Proposed effort allocation, not vendor importance.</p></section><section class="panel"><h2>Six capability pillars</h2><ul>${T.pillars.map(p=>`<li>${p}</li>`).join('')}</ul><a class="button" href="domains.html">Browse eight solution tracks</a></section></div>`);
 $('#roadmap').insertAdjacentHTML('beforeend',`<details class="section-space"><summary>Previous roadmap completion archive</summary><p class="hint">The December sequence changed on 24 November. Previous completion markers remain here and in JSON export; the new sequence starts independently.</p><ul>${(S.legacyDays?.[S.person]||[]).map(n=>`<li>Original day ${n}: ${esc(D.legacyRoadmap[n-1]?.[0]||'Milestone')}</li>`).join('')||'<li>No archived completion markers.</li>'}</ul></details>`);
}
if(page==='insights')leadershipExtension();
